/bin/bash -lc 'python3 -m http.server 4176 --directory . >/tmp/forecast-dashboard-http4.log 2>&1 & server_pid=$!; task_chrome_profile=$(mktemp -d); google-chrome --headless=new --no-sandbox --disable-gpu --remote-debugging-port=9223 --user-data-dir="$task_chrome_profile" about:blank >/tmp/forecast-dashboard-cdp.log 2>&1 & chrome_pid=$!; trap '"'kill \""'$chrome_pid" "$server_pid" 2>/dev/null || true'"' EXIT; for attempt in "'$(seq 1 30); do curl -fsS http://127.0.0.1:9223/json/new?http://127.0.0.1:4176/index.html -X PUT >/tmp/forecast-dashboard-target.json && break; sleep 0.2; done; node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
const target = JSON.parse(await (await fetch('http://127.0.0.1:9223/json/list')).text()).find((entry) => entry.type === 'page');
const socket = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { socket.addEventListener('open', resolve, { once: true }); socket.addEventListener('error', reject, { once: true }); });
let requestId = 0;
const waiting = new Map();
socket.addEventListener('message', (event) => { const message = JSON.parse(event.data); if (message.id && waiting.has(message.id)) { const item = waiting.get(message.id); waiting.delete(message.id); message.error ? item.reject(new Error(message.error.message)) : item.resolve(message.result); } });
const call = (method, params = {}) => new Promise((resolve, reject) => { const id = ++requestId; waiting.set(id, { resolve, reject }); socket.send(JSON.stringify({ id, method, params })); });
const evaluate = async (expression) => (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
await new Promise((resolve) => setTimeout(resolve, 4500));
const initial = await evaluate("'`({median:document.querySelector('"'#median-price').textContent, validation:document.querySelector('#validation-value').textContent, canvas:document.querySelector('#forecast-chart').width})"'`);
assert.match(initial.median, /''^'"\\"'$/);
assert.match(initial.validation, /%/);
assert.ok(initial.canvas > 0);
await evaluate(`document.querySelector('"'#horizon').value = 63; document.querySelector('#horizon').dispatchEvent(new Event('input', {bubbles:true}));"'`);
await new Promise((resolve) => setTimeout(resolve, 800));
const changed = await evaluate(`({horizon:document.querySelector('"'#horizon-value').textContent, median:document.querySelector('#median-price').textContent, scenarios:document.querySelectorAll('#scenarios article').length, chart:document.querySelector('#forecast-chart').width})"'`);
assert.equal(changed.horizon, '"'63 trading days');
assert.match(changed.median, /"'^'"\\"'$/);
assert.equal(changed.scenarios, 3);
assert.ok(changed.chart > 0);
console.log('"'browser interaction smoke test passed', changed);
socket.close();
NODE
"

