await evaluate(`document.querySelector('"'#horizon').value = 65; document.querySelector('#horizon').dispatchEvent(new Event('input', {bubbles:true})); document.querySelector('#simulations').value = 1000; document.querySelector('#simulations').dispatchEvent(new Event('input', {bubbles:true}));"'`);
await new Promise((resolve) => setTimeout(resolve, 900));
const changed = await evaluate(`({horizon: document.querySelector('"'#horizon-value').textContent, paths: document.querySelector('#simulations-value').textContent, cards: document.querySelectorAll('#scenarios article').length, chartWidth: document.querySelector('#forecast-chart').width})"'`);
